// src/lib/pdf.js
async function textoDoPdf(bytes) {
  GlobalWorkerOptions.workerSrc = chrome.runtime.getURL("sidepanel/pdf.worker.min.mjs");
  const pdf = await getDocument({ data: bytes.slice(), isEvalSupported: false }).promise;
  try {
    const partes = [];
    for (let p = 1; p <= pdf.numPages; p++) {
      const conteudo = await (await pdf.getPage(p)).getTextContent();
      partes.push(conteudo.items.map((i) => i.str).join(" "));
    }
    return partes.join("\n");
  } finally {
    await pdf.destroy();
  }
}

// src/lib/config.js
var PADROES = { propriedade: "3", nacionalidade: "BRASILEIRA", emailProprietario: "comercial2@breviis.com.br", telefoneProprietario: "" };
async function lerConfig(storage = chrome.storage.local) {
  const r = await storage.get(["apiKey", "padroes"]);
  return { apiKey: r.apiKey ?? "", padroes: { ...PADROES, ...r.padroes ?? {} } };
}
async function salvarConfig(cfg, storage = chrome.storage.local) {
  await storage.set(cfg);
}

// src/sidepanel/formulario.js
var PROPRIEDADES = [["1", "Da Casa"], ["2", "Agregado"], ["3", "Terceiro"]];
var ESC = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
var esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ESC[c]);
function controle(campo, valor) {
  const nome = `c_${campo.chave}`;
  const opcoes = (lista) => lista.map(([v, t]) => `<option value="${esc(v)}"${v === valor ? " selected" : ""}>${esc(t)}</option>`).join("");
  const select = (lista) => `<select name="${nome}"><option value="">\u2014</option>${opcoes(lista)}</select>`;
  if (campo.tipo === "uf") return select(UFS.map((u) => [u, u]));
  if (campo.tipo === "propriedade") return select(PROPRIEDADES);
  if (campo.tipo === "opcao") return select(campo.opcoes);
  return `<input name="${nome}" value="${esc(valor)}" autocomplete="off">`;
}
function painel(tela, valores) {
  const campos = camposDaTela(tela);
  const grupos = [...new Set(campos.map((c) => c.grupo))];
  return grupos.map((g) => `<fieldset><legend>${esc(g)}</legend>${campos.filter((c) => c.grupo === g).map((c) => {
    const v = valores[c.chave] ?? { valor: "", certeza: "conferir", fonte: "" };
    return `<label class="campo${v.certeza === "conferir" ? " conferir" : ""}"><span>${esc(c.rotulo)}${c.obrigatorio ? " *" : ""}</span>${controle(c, v.valor)}${v.fonte ? `<small>${esc(v.fonte)}</small>` : ""}</label>`;
  }).join("")}</fieldset>`).join("");
}
function montarFormulario(valores) {
  const telas = Object.keys(TELAS);
  const abas = telas.map((t, i) => `<button type="button" class="aba${i === 0 ? " ativa" : ""}" data-tela="${t}">${esc(TELAS[t].rotulo)}</button>`).join("");
  const paineis = telas.map((t, i) => `<div data-painel="${t}"${i === 0 ? "" : " hidden"}>${painel(t, valores)}</div>`).join("");
  return `<div class="abas">${abas}</div>${paineis}`;
}
function mostrarAba(form, tela) {
  for (const b of form.querySelectorAll(".aba")) b.classList.toggle("ativa", b.dataset.tela === tela);
  for (const p of form.querySelectorAll("[data-painel]")) p.hidden = p.dataset.painel !== tela;
}
function lerFormulario(form, tela) {
  const valores = {}, invalidos = [], faltando = [];
  for (const c of CAMPOS) {
    const bruto = form.elements[`c_${c.chave}`]?.value ?? "";
    const v = normalizarCampo(c, bruto);
    valores[c.chave] = v;
    if (tela && c.tela !== tela) continue;
    if (bruto.trim() && !v) invalidos.push(c.rotulo);
    else if (!v && c.obrigatorio) faltando.push(c.rotulo);
  }
  return { valores, invalidos, faltando };
}

// src/lib/versao.js
var RELEASES = "https://github.com/breviistransportes/Sitra_automacao/releases/";
function linkAtualizacaoValido(tag, url) {
  return /^v\d+\.\d+\.\d+$/.test(String(tag ?? "")) && String(url ?? "").startsWith(RELEASES);
}
function versaoMaior(nova, atual) {
  const partes = (v) => String(v ?? "").replace(/^v/i, "").split(".").map(Number);
  const a = partes(nova), b = partes(atual);
  if (a.some(Number.isNaN) || b.some(Number.isNaN)) return false;
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const x = a[i] ?? 0, y = b[i] ?? 0;
    if (x !== y) return x > y;
  }
  return false;
}

// src/sidepanel/main.js
var DOCUMENTO = { motorista: "cpf", proprietario: "prop_cpf_cnpj", veiculo: "veic_placa" };
var $ = (id) => document.getElementById(id);
var arquivos = [];
var confirmarSobrescrita = false;
function mostrar(etapa) {
  for (const s of document.querySelectorAll("section[data-etapa]")) s.hidden = s.dataset.etapa !== etapa;
}
function mensagem(texto, tipo = "erro") {
  $("mensagem").textContent = texto;
  $("mensagem").className = tipo;
  $("mensagem").hidden = !texto;
  if (texto) $("mensagem").scrollIntoView?.({ block: "nearest", behavior: "smooth" });
}
function preencherLista(ul, itens) {
  ul.innerHTML = "";
  for (const t of itens) {
    const li = document.createElement("li");
    li.textContent = t;
    ul.append(li);
  }
}
function listarArquivos() {
  const ul = $("lista-arquivos");
  ul.innerHTML = "";
  arquivos.forEach((f, i) => {
    const li = document.createElement("li");
    li.textContent = f.name;
    const b = document.createElement("button");
    b.textContent = "\u2715";
    b.title = "Remover";
    b.onclick = () => {
      arquivos.splice(i, 1);
      listarArquivos();
    };
    li.append(b);
    ul.append(li);
  });
  atualizarBotaoLer();
}
function atualizarBotaoLer() {
  $("btn-ler").disabled = arquivos.length === 0 && !$("mensagens").value.trim();
}
function adicionar(lista) {
  arquivos.push(...lista);
  listarArquivos();
  mensagem("");
}
async function lerDocumentos() {
  mensagem("");
  const cfg = await lerConfig();
  if (!cfg.apiKey) {
    await abrirConfig("Cole a chave da API do Gemini e clique em Salvar.");
    return;
  }
  mostrar("lendo");
  try {
    const entrada = await lerEntrada(arquivos);
    const docs = await prepararDocumentos(entrada.itens, { redimensionar: redimensionarImagem, lerTextoPdf: textoDoPdf });
    docs.mensagens = $("mensagens").value;
    const avisosEntrada = [
      ...entrada.naoSuportados.map((n) => `${n}: formato n\xE3o suportado \u2014 solte os arquivos direto ou use .zip`),
      ...docs.avisos
    ];
    if (!temConteudo(docs, docs.mensagens)) {
      throw new Error(["Nenhuma foto/PDF encontrada e nenhuma mensagem colada.", ...avisosEntrada].join(" "));
    }
    const textoConfiavel = [docs.mensagens ?? "", ...docs.textos.map((t) => t.conteudo)].join("\n");
    const [bruto, segunda] = await Promise.all([
      chamarGemini(cfg.apiKey, docs),
      chamarGeminiConferencia(cfg.apiKey, docs).catch((e) => ({ erro: e.message }))
    ]);
    if (segunda.erro) avisosEntrada.push(`Segunda leitura indispon\xEDvel (${segunda.erro}) \u2014 confira com aten\xE7\xE3o os n\xFAmeros da CNH.`);
    const textoPdf = docs.pdfs.map((p) => p.texto).join("\n");
    const segundaLeitura = segunda.erro ? null : segunda;
    const terceiraLeitura = camposDivergentes(bruto?.campos, segundaLeitura).length ? await chamarGeminiConferencia(cfg.apiKey, docs).catch(() => null) : null;
    const r = posProcessar(bruto, cfg.padroes, { textoConfiavel, textoPdf, segundaLeitura, terceiraLeitura });
    $("form-conferencia").innerHTML = montarFormulario(r.valores);
    const docsLidos = r.documentos.length ? [`Documentos lidos: ${r.documentos.join(", ")}`] : [];
    preencherLista($("avisos"), [...docsLidos, ...avisosEntrada, ...r.avisos]);
    confirmarSobrescrita = false;
    mostrar("conferencia");
  } catch (e) {
    mostrar("entrada");
    mensagem(e.message);
    $("btn-ler").textContent = "Tentar de novo";
  }
}
async function executarNoSitra(func, args = []) {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (!ehSitra(tab?.url)) throw new Error("A aba ativa n\xE3o \xE9 o Sitra da empresa.");
  await chrome.scripting.executeScript({ target: { tabId: tab.id }, world: "MAIN", files: ["content/injetado.bundle.js"] });
  const [r] = await chrome.scripting.executeScript({ target: { tabId: tab.id }, world: "MAIN", func, args });
  return r.result;
}
var STATUS = { ok: "\u2705", sitra: "\u{1F535} veio do Sitra (CEP) \u2014", falhou: "\u26A0\uFE0F n\xE3o gravou \u2014", vazio: "\u26A0\uFE0F obrigat\xF3rio vazio \u2014" };
function mostrarRelatorio(rel) {
  $("resultado-titulo").textContent = rel.ok ? `Pronto! Confira a tela de ${TELAS[rel.tela].rotulo} no Sitra e clique em "Cadastrar".` : `Parou: ${rel.erro}`;
  const linhas = [
    ...rel.avisos,
    ...rel.campos.map((c) => `${STATUS[c.status]} ${c.rotulo}${c.status === "falhou" ? ` (esperado "${c.esperado}", ficou "${c.obtido}")` : ""}`)
  ];
  preencherLista($("relatorio"), linhas);
  mostrar("resultado");
}
async function preencherSitra() {
  mensagem("");
  let est;
  try {
    est = await executarNoSitra(() => window.__cadastroMotorista.estado());
  } catch {
    est = { tela: null };
  }
  if (!est?.tela) {
    mensagem("Abra no Sitra a tela de Cadastro de Motorista, de Propriet\xE1rio ou de Ve\xEDculo nesta aba.");
    return;
  }
  const form = $("form-conferencia");
  mostrarAba(form, est.tela);
  const { valores, invalidos, faltando } = lerFormulario(form, est.tela);
  const rotuloTela = TELAS[est.tela].rotulo;
  if (invalidos.length) {
    mensagem(`Formato inv\xE1lido (${rotuloTela}): ${invalidos.join(", ")}`);
    return;
  }
  const doc = DOCUMENTO[est.tela];
  if (!valores[doc]) {
    mensagem(`${CAMPO_POR_CHAVE[doc].rotulo} \xE9 obrigat\xF3rio para preencher a tela de ${rotuloTela}.`);
    return;
  }
  if (!est.vazio && !confirmarSobrescrita) {
    confirmarSobrescrita = true;
    mensagem('O formul\xE1rio do Sitra j\xE1 tem dados. Clique em "Preencher no Sitra" de novo para sobrescrever, ou clique em "Limpar" no Sitra antes.', "alerta");
    return;
  }
  confirmarSobrescrita = false;
  if (faltando.length) mensagem(`Vai ficar faltando (${rotuloTela}): ${faltando.join(", ")}`, "alerta");
  $("btn-preencher").disabled = true;
  $("btn-preencher").textContent = "Preenchendo\u2026";
  try {
    mostrarRelatorio(await executarNoSitra((v) => window.__cadastroMotorista.preencher(v), [valoresDaTela(valores, est.tela)]));
  } catch (e) {
    mensagem(`Falha ao preencher: ${e.message}`);
  } finally {
    $("btn-preencher").disabled = false;
    $("btn-preencher").textContent = "Preencher no Sitra";
  }
}
function recomecar() {
  arquivos = [];
  $("mensagens").value = "";
  listarArquivos();
  mensagem("");
  $("btn-ler").textContent = "Ler documentos";
  mostrar("entrada");
}
$("zona").addEventListener("dragover", (e) => {
  e.preventDefault();
  $("zona").classList.add("ativa");
});
$("zona").addEventListener("dragleave", () => $("zona").classList.remove("ativa"));
$("zona").addEventListener("drop", (e) => {
  e.preventDefault();
  $("zona").classList.remove("ativa");
  adicionar([...e.dataTransfer.files]);
});
$("seletor").addEventListener("change", (e) => {
  adicionar([...e.target.files]);
  e.target.value = "";
});
$("zona").addEventListener("keydown", (e) => {
  if (e.key === "Enter" || e.key === " ") {
    e.preventDefault();
    $("seletor").click();
  }
});
$("btn-ler").addEventListener("click", lerDocumentos);
$("mensagens").addEventListener("input", atualizarBotaoLer);
$("btn-preencher").addEventListener("click", (e) => {
  e.preventDefault();
  preencherSitra();
});
$("btn-recomecar").addEventListener("click", recomecar);
$("btn-novo").addEventListener("click", recomecar);
$("btn-voltar").addEventListener("click", () => {
  mensagem("");
  mostrar("conferencia");
});
$("link-config").addEventListener("click", (e) => {
  e.preventDefault();
  abrirConfig();
});
$("cfg-salvar").addEventListener("click", salvarConfigPainel);
$("cfg-fechar").addEventListener("click", () => {
  $("config").hidden = true;
  mensagem("");
});
$("form-conferencia").addEventListener("input", (e) => e.target.closest("label")?.classList.remove("conferir"));
$("form-conferencia").addEventListener("submit", (e) => e.preventDefault());
$("form-conferencia").addEventListener("click", (e) => {
  const aba = e.target.closest(".aba");
  if (aba) mostrarAba($("form-conferencia"), aba.dataset.tela);
});
async function verificarAtualizacao() {
  try {
    const r = await fetch("https://api.github.com/repos/breviistransportes/Sitra_automacao/releases/latest");
    if (!r.ok) return;
    const { tag_name: tag, html_url: url } = await r.json();
    if (!linkAtualizacaoValido(tag, url) || !versaoMaior(tag, chrome.runtime.getManifest().version)) return;
    $("link-atualizacao").href = url;
    $("link-atualizacao").textContent = `Nova vers\xE3o ${tag} dispon\xEDvel \u2014 baixar`;
    $("atualizacao").hidden = false;
  } catch {
  }
}
verificarAtualizacao();
async function abrirConfig(aviso = "") {
  const cfg = await lerConfig();
  $("cfg-apiKey").value = cfg.apiKey;
  $("cfg-nacionalidade").value = cfg.padroes.nacionalidade;
  $("cfg-propriedade").value = cfg.padroes.propriedade;
  $("cfg-emailProprietario").value = cfg.padroes.emailProprietario;
  $("cfg-telefoneProprietario").value = cfg.padroes.telefoneProprietario;
  $("config").hidden = false;
  mensagem(aviso, "alerta");
  $("cfg-apiKey").focus();
}
async function salvarConfigPainel() {
  const apiKey = $("cfg-apiKey").value.trim();
  if (!apiKey) {
    mensagem("Cole a chave da API do Gemini.");
    return;
  }
  await salvarConfig({
    apiKey,
    padroes: {
      nacionalidade: $("cfg-nacionalidade").value.trim().toUpperCase(),
      propriedade: $("cfg-propriedade").value,
      emailProprietario: $("cfg-emailProprietario").value.trim().toLowerCase(),
      telefoneProprietario: $("cfg-telefoneProprietario").value.trim()
    }
  });
  $("config").hidden = true;
  mensagem("Configura\xE7\xF5es salvas.", "alerta");
}
lerConfig().then((cfg) => {
  if (!cfg.apiKey) abrirConfig("Primeiro uso: cole a chave da API do Gemini e clique em Salvar.");
}).catch(() => {
});
